constexpr int kMaxVariableBeats = 20000;

/// Length of the first beat in frames (Beats::firstBeatLengthFrames() is private).
double beatLengthFrames(const BeatsPointer& pBeats) {
    const audio::FramePos first = pBeats->firstBeat();
    const audio::FramePos second = pBeats->findNthBeat(first, 2);
    return first.isValid() && second.isValid() ? second - first : 0.0;
}

struct Boundary {
    double beat;
    QString role;
    int priority; // lower wins when two boundaries are close
};

QString moodFromText(const QString& text) {
    static const QStringList kMoods = {QStringLiteral("dark"),
            QStringLiteral("euphoric"),
            QStringLiteral("happy"),
            QStringLiteral("melancholic"),
            QStringLiteral("aggressive"),
            QStringLiteral("chill"),
            QStringLiteral("dreamy"),
            QStringLiteral("groovy"),
            QStringLiteral("epic"),
            QStringLiteral("neutral")};
    const QString t = text.toLower();
    for (const QString& m : kMoods) {
        if (t.contains(m)) {
            return m;
        }
    }
    // Rough guess from the genre.
    if (t.contains(QStringLiteral("techno")) || t.contains(QStringLiteral("industrial"))) {
        return QStringLiteral("dark");
    }
    if (t.contains(QStringLiteral("trance")) || t.contains(QStringLiteral("progressive"))) {
        return QStringLiteral("euphoric");
    }
    if (t.contains(QStringLiteral("house")) || t.contains(QStringLiteral("funk")) ||
            t.contains(QStringLiteral("disco")) || t.contains(QStringLiteral("salsa")) ||
            t.contains(QStringLiteral("cumbia")) || t.contains(QStringLiteral("reggaeton"))) {
        return QStringLiteral("groovy");
    }
    if (t.contains(QStringLiteral("ambient")) || t.contains(QStringLiteral("chill")) ||
            t.contains(QStringLiteral("lounge")) || t.contains(QStringLiteral("downtempo"))) {
        return QStringLiteral("chill");
    }
    if (t.contains(QStringLiteral("metal")) || t.contains(QStringLiteral("hardstyle")) ||
            t.contains(QStringLiteral("drum")) || t.contains(QStringLiteral("dubstep"))) {
        return QStringLiteral("aggressive");
    }
    if (t.contains(QStringLiteral("pop"))) {
        return QStringLiteral("happy");
    }
    return QStringLiteral("neutral");
}

QStringList paletteFor(const RgbColor::optional_t& color, const QString& mood) {
    if (color) {
        const QColor c = RgbColor::toQColor(*color);
        const QColor complement = QColor::fromHsv((c.hsvHue() + 180) % 360,
                std::max(c.hsvSaturation(), 120),
                std::max(c.value(), 160));
        return {c.name(), c.darker(220).name(), complement.name()};
    }
    if (mood == QLatin1String("dark")) {
        return {QStringLiteral("#1B0A3C"), QStringLiteral("#6A00FF"), QStringLiteral("#FF2E88")};
    }
    if (mood == QLatin1String("euphoric")) {
        return {QStringLiteral("#FFB000"), QStringLiteral("#FF5E00"), QStringLiteral("#FFFFFF")};
    }
    if (mood == QLatin1String("chill")) {
        return {QStringLiteral("#003B46"), QStringLiteral("#07575B"), QStringLiteral("#66A5AD")};
    }
    if (mood == QLatin1String("aggressive")) {
        return {QStringLiteral("#FF0000"), QStringLiteral("#200000"), QStringLiteral("#FFFFFF")};
    }
    if (mood == QLatin1String("groovy")) {
        return {QStringLiteral("#FF7A00"), QStringLiteral("#8E2DE2"), QStringLiteral("#00C2A8")};
    }
    return {QStringLiteral("#3A7BFF"), QStringLiteral("#FFFFFF"), QStringLiteral("#FF2E88")};
}

