    QJsonObject meta;
    meta[QStringLiteral("title")] = pTrack->getTitle();
    meta[QStringLiteral("artist")] = pTrack->getArtist();
    meta[QStringLiteral("album")] = pTrack->getAlbum();
    meta[QStringLiteral("genre")] = pTrack->getGenre();
