            info.sections.append(s);
            QJsonObject o;
            o[QStringLiteral("start_beat")] = s.startBeat;
            o[QStringLiteral("end_beat")] = s.endBeat;
            o[QStringLiteral("role")] = s.role;
            o[QStringLiteral("energy")] = s.energy;
            o[QStringLiteral("confidence")] = merged[i].priority == 0 ? 1.0 : 0.6;
